CREATE PROCEDURE [bud].[jsApproveBudget]   @docId INT =8709,   @company  INT = 1,      @userId INT =77,      @remarks NVARCHAR(MAX) = 'Approve',      @action NVARCHAR(20) = 'Approve'  AS  BEGIN      SET NOCOUNT ON;      DECLARE @Message NVARCHAR(4000);        BEGIN TRY          BEGIN TRANSACTION;            DECLARE @templateId INT;          DECLARE @totalStages INT;          DECLARE @currentStage INT;          DECLARE @currentStageId INT;          DECLARE @previousStage INT;          DECLARE @previousStageId INT;          DECLARE @approvalRequired INT;          DECLARE @approvedCount INT;          DECLARE @existingStatus NVARCHAR(50) = 'None';          DECLARE @currentStageActions INT;          DECLARE @userStage INT;          DECLARE @userStageId INT;          DECLARE @nextStageId INT;    DECLARE @currentDocStatus NVARCHAR(10);                    -- Get budget details          SELECT               @templateId = templateId,              @totalStages = totalStage,              @currentStage = currentSatge          FROM bud.jsDocEntry          WHERE id = @docId                    -- If budget not found, throw error          IF @templateId IS NULL          BEGIN              THROW 50001, 'Budget not found with the specified parameters', 1;          END                    -- Get Current Stage ID          SELECT @currentStageId = stageId           FROM jsStageTemplate          WHERE templateId = @templateId AND priority = @currentStage;                    -- Get Previous Stage ID          SET @previousStage = @currentStage - 1;          SELECT @previousStageId = stageId           FROM jsStageTemplate          WHERE templateId = @templateId AND priority = @previousStage;                    -- Determine which stage this user belongs to          SELECT TOP 1 @userStage = jst.priority, @userStageId = jst.stageId          FROM jsUserStage us          JOIN jsStageTemplate jst ON us.stageId = jst.stageId          WHERE us.userId = @userId          AND jst.templateId = @templateId          ORDER BY jst.priority;                    -- Check if user belongs to any stage in this template          IF @userStage IS NULL          BEGIN              THROW 50002, 'User is not assigned to any stage in this budget approval workflow', 1;          END                    -- Check if any approvals exist in the current stage          SELECT @currentStageActions = COUNT(*)           FROM bud.jsBudgetStatusWorkflow           WHERE docId = @docId           AND stageId = @currentStageId;            -- APPROVAL LOGIC          IF @action = 'Approve'          BEGIN              -- Check if the user is in the current or previous stage (if no action has been taken in current stage)              IF NOT EXISTS (                  SELECT 1                   FROM jsStageTemplate                  WHERE templateId = @templateId                     AND (stageId = @currentStageId OR (@currentStageActions = 0 AND stageId = @previousStageId))                    AND EXISTS (SELECT 1 FROM jsUserStage WHERE stageId = jsStageTemplate.stageId AND userId = @userId)              )              BEGIN                  THROW 50006, 'User is not authorized to approve this budget.', 1;              END                            -- Check if the user has already taken action              SELECT TOP 1 @existingStatus = status               FROM bud.jsBudgetStatusWorkflow              WHERE docId = @docId               AND stageId = @userStageId              AND userId = @userId               ORDER BY createdOn DESC;                            -- Prevent duplicate approvals in the same stage              IF @existingStatus = 'A' AND @userStage = @currentStage              BEGIN                  THROW 50020, 'User has already approved this budget.', 1;              END                            -- Handle previously approved users who want to re-approve              IF @existingStatus = 'A' AND @userStage < @currentStage AND @currentStageActions = 0              BEGIN                  -- Update the budget status to move back to this user's stage                  UPDATE bud.jsDocEntry           SET currentSatge = @userStage,                      currentStageId = @userStageId,       updatedOn = GETDATE()                  WHERE id = @docId           --------------------------------------------------            SELECT @currentDocStatus = status FROM bud.jsDocEntry WHERE id = @docId;        IF @currentDocStatus = 'R'      BEGIN       UPDATE bud.jsDocEntry       SET status = 'P', updatedOn = GETDATE()       WHERE id = @docId;      END      --------------------------------------------------                     --Sync to HANA                  --EXEC [bud].[jsSyncBudgetStatusToHana]                   --    @docId, @company, 'P', @userStage;                                    SET @Message = 'Budget moved back to previous stage for re-approval';              END                            -- Insert or update approval entry              IF @existingStatus IS NULL OR @existingStatus = 'None'              BEGIN                  -- Insert local record                  INSERT INTO bud.jsBudgetStatusWorkflow                       (docId, status, stageId, templateId, userId, createdOn, description)                  VALUES                       (@docId,'A', @userStageId, @templateId, @userId, GETDATE(), @remarks);                                    -- Sync to HANA                  --EXEC [bud].[jsSyncBudgetWorkflowToHana]                   --    @docId, @company, 'A', @userStageId, @templateId, @userId, @remarks, 1;              END              ELSE              BEGIN                  -- Update local record                  UPDATE bud.jsBudgetStatusWorkflow                   SET status = 'A', description = @remarks, createdOn = GETDATE()                   WHERE docId = @docId                  AND stageId = @userStageId                  AND userId = @userId;        ----------------------------------------------      SELECT @currentDocStatus = status FROM bud.jsDocEntry WHERE id = @docId;        IF @currentDocStatus = 'R'      BEGIN       UPDATE bud.jsDocEntry       SET status = 'P', updatedOn = GETDATE()       WHERE id = @docId;      END      -----------------------------------------------                                    -- Sync to HANA                  --EXEC [bud].[jsSyncBudgetWorkflowToHana]                   --    @docId, @company, 'A', @userStageId, @templateId, @userId, @remarks, 0;              END                            -- Re-evaluate the current stage (which may have changed)              SELECT @currentStage = currentSatge              FROM bud.jsDocEntry              WHERE id = @docId                             -- Get updated Current Stage ID              SELECT @currentStageId = stageId               FROM jsStageTemplate              WHERE templateId = @templateId AND priority = @currentStage;                             -- Check the number of approvals required for the CURRENT stage              SELECT @approvalRequired = approval               FROM jsStage               INNER JOIN jsApprovalCount ON jsStage.approvalId = jsApprovalCount.id               WHERE jsStage.id = @currentStageId;                             -- Count approvals in the CURRENT stage only              SELECT @approvedCount = COUNT(*)               FROM bud.jsBudgetStatusWorkflow               WHERE docId = @docId              AND stageId = @currentStageId              AND status = 'A';                            -- Move to next stage or mark as Approved              IF @approvedCount >= @approvalRequired              BEGIN                  IF @currentStage = @totalStages                  BEGIN                      DECLARE @status NVARCHAR(100);                                            IF @status = 'Data is in SAP for DocEntry'                      BEGIN                          THROW 50010, 'Data is in SAP for DocEntry. Rolling back transaction.', 1;                      END                      ELSE                      BEGIN       -- Update local status                          UPDATE bud.jsDocEntry                           SET status = 'A',updatedOn = GETDATE()                          WHERE id = @docId                                   -- Sync to HANA Budget Status                          --EXEC [bud].[jsSyncBudgetStatusToHana]                           --    @docId, @company, 'A', NULL;                                                        -- Sync to HANA Draft Approval with status 'A' for final approval                          EXEC [bud].[jsSyncBudgetToHanaDraftApproval]                              @docId, @company, 'A', @userId, @remarks;                                                    SET @Message = 'Budget approved and marked as Approved';                      END                  END                  ELSE                  BEGIN                      -- Calculate next stage number and ID                      DECLARE @nextStage INT;                      SET @nextStage = @currentStage + 1;                                            -- Get the next stage ID based on priority                      SELECT @nextStageId = stageId                       FROM jsStageTemplate                      WHERE templateId = @templateId AND priority = @nextStage;                                            -- Update local status to next stage with correct stageId                      UPDATE bud.jsDocEntry                       SET currentSatge = @nextStage,                          currentStageId = @nextStageId,        updatedOn = GETDATE()                      WHERE id = @docId                                            -- Sync to HANA Draft Approval with status 'V' for verification (intermediate approval)                      EXEC [bud].[jsSyncBudgetToHanaDraftApproval]                          @docId, @company, 'V', @userId, @remarks;                        --EXEC [bud].[jsSyncBudgetStatusToHana]                         --  @docId, @company, NULL, @nextStage;                                            SET @Message = 'Budget moved to next stage';                  END              END              ELSE              BEGIN                  -- Avoid string concatenation entirely by using a stored procedure                  EXEC sp_executesql                       N'SELECT @Result = ''Not enough approvals to move to next stage. Current: '' + CAST(@CurrentCount AS NVARCHAR) + '', Required: '' + CAST(@RequiredCount AS NVARCHAR)',                      N'@CurrentCount INT, @RequiredCount INT, @Result NVARCHAR(4000) OUTPUT',                      @approvedCount, @approvalRequired, @Message OUTPUT;              END          END          -- REVOKE APPROVAL LOGIC          ELSE IF @action = 'Revoke'          BEGIN              -- Check if this user is from a previous stage              IF @userStage < @currentStage              BEGIN                  -- Check if any actions have been taken in the current stage                  IF @currentStageActions = 0                  BEGIN                      -- Prepare description for update                      DECLARE @newDescription NVARCHAR(MAX);                      SELECT @newDescription = ISNULL(description, '') FROM bud.jsBudgetStatusWorkflow                      WHERE docId = @docId                      AND stageId = @userStageId                      AND userId = @userId;                                            -- Use sp_executesql to safely concatenate strings                      EXEC sp_executesql                           N'SELECT @Result = @Existing + '' | Revoked: '' + @RemarkText',                          N'@Existing NVARCHAR(MAX), @RemarkText NVARCHAR(MAX), @Result NVARCHAR(MAX) OUTPUT',                          @newDescription, @remarks, @newDescription OUTPUT;                                            -- Allow the user to revoke their approval                      UPDATE bud.jsBudgetStatusWorkflow                      SET status = 'Revoked',                           description = @newDescription,            createdOn = GETDATE()                      WHERE docId = @docId                      AND stageId = @userStageId                      AND userId = @userId                      AND status = 'A';                                            -- Sync to HANA                  --EXEC [bud].[jsSyncBudgetWorkflowToHana]                     --      @docId, @company, 'Revoked', @userStageId, @templateId, @userId,                     --      @newDescription, 0;                                            -- Move the budget back to the user's stage                      UPDATE bud.jsDocEntry                      SET currentSatge = @userStage,                          currentStageId = @userStageId,                          status = 'P'                      WHERE id = @docId                        -- Sync to HANA Budget Status                      --EXEC [bud].[jsSyncBudgetStatusToHana]                       --    @docId, @company, 'P', @userStage;                                            SET @Message = 'Approval revoked and budget returned to previous stage';                  END                  ELSE                  BEGIN                      THROW 50007, 'Cannot revoke approval because actions have already been taken in the current stage', 1;                  END              END              ELSE              BEGIN                  THROW 50008, 'Only users from previous stages can revoke approvals', 1;              END          END          ELSE          BEGIN              THROW 50009, 'Invalid action specified. Use "Approve" or "Revoke"', 1;          END                    COMMIT TRANSACTION;                    -- Return the message as part of the result set          SELECT @Message AS ResultMessage;      END TRY      BEGIN CATCH          IF @@TRANCOUNT > 0          BEGIN              ROLLBACK TRANSACTION;          END                        DECLARE @ErrorMessage NVARCHAR(4000),                  @ErrorSeverity INT,                  @ErrorState INT;                            SELECT               @ErrorMessage = ERROR_MESSAGE(),              @ErrorSeverity = ERROR_SEVERITY(),              @ErrorState = ERROR_STATE();                    INSERT INTO bud.jsErrorLog (docId, errorMessage)          VALUES (@docId, @ErrorMessage);                        RAISERROR (@ErrorMessage, @ErrorSeverity, @ErrorState);      END CATCH  END;
